const URL_CONTATOS = "https://jsonplaceholder.typicode.com/users";
const botao = document.getElementById("botao-carregar");
const statusMsg = document.getElementById("status-msg");
const lista = document.getElementById("lista-contatos");

function criarItemContato(contato) {
  const li = document.createElement("li");
  li.textContent = `${contato.name} — ${contato.email} (${contato.address.city})`;
  return li;
}

function renderizarContatos(contatos) {
  lista.innerHTML = "";
  contatos.forEach(contato => {
    lista.appendChild(criarItemContato(contato));
  });
  statusMsg.textContent = `${contatos.length} contatos carregados.`;
}

function carregarContatos() {
  statusMsg.textContent = "Carregando...";
  botao.disabled = true;

  fetch(URL_CONTATOS)
    .then(res => {
      if (!res.ok) {
        throw new Error(`Erro HTTP: ${res.status}`);
      }
      return res.json();
    })
    .then(renderizarContatos)
    .catch(erro => {
      statusMsg.textContent = "Não foi possível carregar os contatos. Tente novamente.";
      console.error("Detalhe do erro:", erro);
    })
    .finally(() => {
      botao.disabled = false;
    });
}

botao.addEventListener("click", carregarContatos);

