const erroMsg = document.getElementById("erro");
fetch(`${BASE}/posts/99999`)
  .then(res => {
    if (!res.ok) throw new Error(`Post não encontrado (${res.status})`);
    return res.json();
  })
  .then(post => console.log(post))
  .catch(erro => erroMsg.textContent = erro.message);

function criarCartao(post) {
  const div = document.createElement("div");
  const h3 = document.createElement("h3");
  const p = document.createElement("p");
  h3.textContent = post.title;
  p.textContent = post.body;
  div.appendChild(h3);
  div.appendChild(p);
  return div;
}

function renderizarPosts(posts) {
  const area = document.getElementById("area-posts");
  area.innerHTML = "";
  posts.forEach(post => area.appendChild(criarCartao(post)));
}

fetch(`${BASE}/posts?_limit=3`)
  .then(res => res.json())
  .then(renderizarPosts)
  .catch(erro => console.error(erro));

const campo = document.getElementById("numero");
const saida = document.getElementById("saida");

document.getElementById("buscar").addEventListener("click", () => {
  fetch(`${BASE}/users/${campo.value}`)
    .then(res => {
      if (!res.ok) throw new Error("Usuário não encontrado");
      return res.json();
    })
    .then(usuario => saida.textContent = usuario.name)
    .catch(erro => {
      // erro de rede chega como TypeError ("Failed to fetch")
      saida.textContent = erro instanceof TypeError
        ? "Verifique sua conexão"
        : erro.message;
    });
});

